+const settle=()=>new Promise(resolve=>setImmediate(resolve));
+const ok=body=>({ok:true,status:200,json:async()=>copy(body)});
+
+function database(){
+ const cards=new Map(),ops=new Map(),history=[];
+ const db={cards,ops,history,
